function obstacle = obs_attach_motion(obstacle,motion)
% 静的障害物の形状をそのまま使い、障害物単位で独立した軌道を付加する。
assert(isstruct(obstacle) && isscalar(obstacle) && isfield(obstacle,'type'), ...
    'obstacle must be one obstacle generated by obs_*');
assert(isstruct(motion) && isfield(motion,'type'),'motion must be an obs_motion_* struct');
obstacle.motion = motion;
obstacle.isDynamic = ~strcmp(motion.type,'static');
end
